/* Where a digital key comes from at the moment of sale.
 *
 * The system does not keep a key inventory. Stocking DEMO keys up front only
 * ever produced a number ("650 keys in stock") that meant nothing: the keys were
 * generated by this same repository, so claiming one was picking from a shelf we
 * had filled ourselves.
 *
 * Instead the key is obtained when the order is fulfilled, which is also how a
 * real reseller works — the publisher hands over a key against a paid order.
 *
 * Two sources, in order:
 *   1. KEY_SUPPLIER_URL, when configured. POST { game, edition, orderId } and
 *      expect { key } back. This is the production path. Real suppliers are
 *      B2B wholesale APIs (CodesWholesale, Xsolla, GameKeyDistribution, ...) —
 *      point KEY_SUPPLIER_URL at your own supplier endpoint (or a small proxy
 *      that maps your catalog to their product ids) and set KEY_SUPPLIER_TOKEN
 *      when it uses a bearer token.
 *   2. No supplier configured: generate a DEMO placeholder locally. Every such
 *      key is prefixed DEMO so it can never be mistaken for a real one, and the
 *      rest of the pipeline (encryption, hashing, delivery) is unchanged — only
 *      where the string comes from is different.
 *
 * A supplier that errors is NOT swallowed into a generated key. Reporting a
 * fake success for a paid order is worse than reporting a failure, so the error
 * propagates and fulfilOrder records it on the order.
 */
const { makeDemoKey } = require('./keyCrypto');

function supplierConfigured() {
  return Boolean(process.env.KEY_SUPPLIER_URL);
}

/* Give the supplier a bounded window. A hung third-party call must not hold the
   payment callback open indefinitely. */
async function fetchWithTimeout(url, options, ms = 8000) {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), ms);
  try {
    const res = await fetch(url, { ...options, signal: ctrl.signal });
    if (!res.ok) throw new Error(`supplier replied ${res.status}`);
    return await res.json();
  } finally {
    clearTimeout(timer);
  }
}

async function requestFromSupplier({ game, edition, orderId, qty }) {
  const url = process.env.KEY_SUPPLIER_URL;
  const token = process.env.KEY_SUPPLIER_TOKEN;
  const keyField = process.env.KEY_SUPPLIER_KEY_FIELD || 'key';
  const headers = { 'content-type': 'application/json' };
  if (token) headers.authorization = `Bearer ${token}`;

  const out = [];
  for (let i = 0; i < qty; i++) {
    const body = await fetchWithTimeout(url, {
      method: 'POST',
      headers,
      body: JSON.stringify({ game, edition, orderId }),
    });
    const key = body && body[keyField];
    if (!key || typeof key !== 'string') {
      throw new Error('supplier returned no key');
    }
    out.push(key.trim());
  }
  return out;
}

/* Returns { source, keys }. `source` is 'supplier' or 'demo' and is stored on
   the issued-key document so it is always visible which path produced a key. */
async function issueKeys({ game, edition, orderId, qty }) {
  if (!qty || qty < 1) return { source: 'demo', keys: [] };

  if (supplierConfigured()) {
    const keys = await requestFromSupplier({ game, edition, orderId, qty });
    return { source: 'supplier', keys };
  }

  return { source: 'demo', keys: Array.from({ length: qty }, () => makeDemoKey()) };
}

module.exports = { issueKeys, supplierConfigured };
